CREATE TABLE reported_balance_import_batches(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,rows_json TEXT NOT NULL CHECK(json_valid(rows_json) AND json_type(rows_json)='array'),created_by TEXT NOT NULL REFERENCES "user"(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reported_balance_import_refs(source_ref TEXT PRIMARY KEY NOT NULL,observation_id TEXT NOT NULL UNIQUE REFERENCES reported_loan_balances(id),batch_id TEXT NOT NULL REFERENCES reported_balance_import_batches(id));
CREATE TRIGGER reported_balance_import_validate BEFORE INSERT ON reported_balance_import_batches BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN json_array_length(NEW.rows_json) NOT BETWEEN 1 AND 100 THEN RAISE(ABORT,'invalid batch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.id') IS NOT 'text' OR length(json_extract(r.value,'$.id')) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.sourceRef') IS NOT 'text' OR length(trim(json_extract(r.value,'$.sourceRef'))) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.loanRef') IS NOT 'text' OR length(trim(json_extract(r.value,'$.loanRef'))) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.amountMinor') IS NOT 'text' OR length(json_extract(r.value,'$.amountMinor')) NOT BETWEEN 1 AND 30 OR json_extract(r.value,'$.amountMinor') GLOB '*[^0-9]*' OR (length(json_extract(r.value,'$.amountMinor'))>1 AND substr(json_extract(r.value,'$.amountMinor'),1,1)='0') OR json_type(r.value,'$.basis') IS NOT 'text' OR length(trim(json_extract(r.value,'$.basis'))) NOT BETWEEN 1 AND 500 OR json_type(r.value,'$.source') IS NOT 'text' OR length(trim(json_extract(r.value,'$.source'))) NOT BETWEEN 1 AND 500 OR date(json_extract(r.value,'$.observedDate'),'+0 days') IS NOT json_extract(r.value,'$.observedDate') OR json_extract(r.value,'$.observedDate')<json_extract(r.value,'$.disbursementDate') OR json_extract(r.value,'$.observedDate')>date('now','+3 hours')) THEN RAISE(ABORT,'invalid observation') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r GROUP BY json_extract(r.value,'$.sourceRef') HAVING count(*)>1) OR EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r JOIN reported_balance_import_refs x ON x.source_ref=json_extract(r.value,'$.sourceRef')) THEN RAISE(ABORT,'source reference conflict') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE NOT EXISTS(SELECT 1 FROM loans l JOIN members m ON m.id=l.member_id WHERE (json_extract(r.value,'$.loanRef')='id:'||l.id OR (substr(json_extract(r.value,'$.loanRef'),1,3)<>'id:' AND EXISTS(SELECT 1 FROM lending_import_refs x WHERE x.kind='loan' AND x.record_id=l.id AND x.source_ref=json_extract(r.value,'$.loanRef')))) AND l.id=json_extract(r.value,'$.loanId') AND l.member_id=json_extract(r.value,'$.memberId') AND m.member_number=json_extract(r.value,'$.memberNumber') AND m.full_name=json_extract(r.value,'$.memberName') AND m.status=json_extract(r.value,'$.memberStatus') AND l.currency=json_extract(r.value,'$.currency') AND CAST(l.principal_minor AS TEXT)=json_extract(r.value,'$.principalMinor') AND l.disbursement_date=json_extract(r.value,'$.disbursementDate') AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id))) THEN RAISE(ABORT,'loan changed or unavailable') END;
END;
CREATE TRIGGER reported_balance_import_apply AFTER INSERT ON reported_balance_import_batches BEGIN
 INSERT INTO reported_loan_balances(id,loan_id,member_id,currency,disbursement_date,principal_minor,observed_date,amount_minor,basis,source,request_key,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.loanId'),json_extract(r.value,'$.memberId'),json_extract(r.value,'$.currency'),json_extract(r.value,'$.disbursementDate'),json_extract(r.value,'$.principalMinor'),json_extract(r.value,'$.observedDate'),json_extract(r.value,'$.amountMinor'),json_extract(r.value,'$.basis'),json_extract(r.value,'$.source'),json_extract(r.value,'$.id'),NEW.created_by FROM json_each(NEW.rows_json) r;
 INSERT INTO reported_balance_import_refs(source_ref,observation_id,batch_id) SELECT json_extract(r.value,'$.sourceRef'),json_extract(r.value,'$.id'),NEW.id FROM json_each(NEW.rows_json) r;
END;
CREATE TRIGGER reported_balance_import_no_update BEFORE UPDATE ON reported_balance_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER reported_balance_import_no_delete BEFORE DELETE ON reported_balance_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER reported_balance_refs_no_update BEFORE UPDATE ON reported_balance_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
CREATE TRIGGER reported_balance_refs_no_delete BEFORE DELETE ON reported_balance_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
